function sparkParse(s){
  if(typeof s!=='string') return [];
  return s.split(/[\s,;]+/).map(function(x){ return parseFloat(x); }).filter(function(x){ return !isNaN(x); });
}
function sparkLine(values, opts){
  opts=opts||{};
  values=values.map(Number);
  if(values.length===0) return {error:'empty', svg:''};
  var w=opts.width||240, h=opts.height||80, pad=opts.pad||4;
  var fill=opts.fill!==false, dot=opts.dot!==false;
  var stroke=opts.stroke||'#22D3EE', fillc=opts.fillColor||'rgba(34,211,238,0.18)';
  var min=Math.min.apply(null,values), max=Math.max.apply(null,values);
  if(min===max){ min-=1; max+=1; }
  var n=values.length;
  var innerW=w-pad*2, innerH=h-pad*2;
  var pts=[];
  for(var i=0;i<n;i++){
    var x = pad + (n===1?innerW/2:(innerW*i/(n-1)));
    var y = pad + innerH*(1-(values[i]-min)/(max-min));
    pts.push([x,y]);
  }
  var poly=pts.map(function(p){ return p[0].toFixed(1)+','+p[1].toFixed(1); }).join(' ');
  var body='<polyline fill="none" stroke="'+stroke+'" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" points="'+poly+'"/>';
  if(fill){
    var areaPoly=poly+' '+pts[n-1][0].toFixed(1)+','+(h-pad).toFixed(1)+' '+pts[0][0].toFixed(1)+','+(h-pad).toFixed(1);
    body='<polygon fill="'+fillc+'" points="'+areaPoly+'"/>'+body;
  }
  if(dot){
    var last=pts[n-1];
    body+='<circle cx="'+last[0].toFixed(1)+'" cy="'+last[1].toFixed(1)+'" r="3" fill="'+stroke+'"/>';
  }
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">'+
          '<rect width="'+w+'" height="'+h+'" fill="#0A0A0B"/>'+body+'</svg>';
  return {svg:svg, points:pts, min:min, max:max, error:null};
}
function sparkBars(values, opts){
  opts=opts||{};
  values=values.map(Number);
  if(values.length===0) return {error:'empty', svg:''};
  var w=opts.width||240, h=opts.height||80, pad=opts.pad||4;
  var color=opts.color||'#5E6AD2';
  var min=Math.min.apply(null,values), max=Math.max.apply(null,values);
  if(min===max){ min=0; }
  var n=values.length;
  var innerW=w-pad*2, innerH=h-pad*2;
  var bw=innerW/n;
  var bars='';
  for(var i=0;i<n;i++){
    var vh=max===min?innerH:(innerH*(values[i]-min)/(max-min));
    if(vh<1) vh=1;
    var x=pad+bw*i, y=pad+innerH-vh;
    bars+='<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+(bw*0.7).toFixed(1)+'" height="'+vh.toFixed(1)+'" rx="1" fill="'+color+'"/>';
  }
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">'+
          '<rect width="'+w+'" height="'+h+'" fill="#0A0A0B"/>'+bars+'</svg>';
  return {svg:svg, min:min, max:max, error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { line:sparkLine, bars:sparkBars, parse:sparkParse };
}
if (typeof window !== 'undefined') {
  window.SparkForgePure = { line:sparkLine, bars:sparkBars, parse:sparkParse };
}
